import asyncio
import os
import sys
import time
from dataclasses import dataclass
from typing import Any


@dataclass
class SandboxConfig:
    """Security and resource limits for sandboxed execution."""
    timeout_seconds: float = 5.0
    max_output_bytes: int = 50_000
    memory_limit_mb: int = 128


@dataclass
class SandboxResult:
    """Output generated by sandboxed code execution."""
    stdout: str
    stderr: str
    exit_code: int
    duration_seconds: float
    timed_out: bool = False
    truncated: bool = False


class CodeSandboxRunner:
    """Sandboxed execution runner with timeout, memory, and output isolation."""

    def __init__(self, default_config: SandboxConfig | None = None):
        self.config = default_config or SandboxConfig()

    async def execute_python(self, code: str, config: SandboxConfig | None = None) -> SandboxResult:
        """Executes Python code in an isolated subprocess with strict safety constraints."""
        cfg = config or self.config
        start_time = time.time()

        # Wrap code to prevent interactive prompts or stalling
        harness = (
            "import sys\n"
            "try:\n"
            "    exec(sys.stdin.read(), {'__builtins__': __builtins__})\n"
            "except Exception as e:\n"
            "    sys.stderr.write(f'{type(e).__name__}: {str(e)}\\n')\n"
            "    sys.exit(1)\n"
        )

        try:
            # Spawn isolated subprocess without inherited shell or networking
            proc = await asyncio.create_subprocess_exec(
                sys.executable,
                "-u",
                "-c",
                harness,
                stdin=asyncio.subprocess.PIPE,
                stdout=asyncio.subprocess.PIPE,
                stderr=asyncio.subprocess.PIPE,
            )

            try:
                stdout_bytes, stderr_bytes = await asyncio.wait_for(
                    proc.communicate(input=code.encode("utf-8")),
                    timeout=cfg.timeout_seconds,
                )
                duration = time.time() - start_time
                exit_code = proc.returncode or 0
                timed_out = False

            except asyncio.TimeoutError:
                try:
                    proc.kill()
                    await proc.wait()
                except ProcessLookupError:
                    pass
                duration = time.time() - start_time
                return SandboxResult(
                    stdout="",
                    stderr=f"Execution timed out after {cfg.timeout_seconds:.1f} seconds.",
                    exit_code=124,
                    duration_seconds=duration,
                    timed_out=True,
                )

        except Exception as e:
            return SandboxResult(
                stdout="",
                stderr=f"Failed to spawn sandbox subprocess: {str(e)}",
                exit_code=1,
                duration_seconds=time.time() - start_time,
            )

        # Output truncation
        stdout_text = stdout_bytes.decode("utf-8", errors="replace")
        stderr_text = stderr_bytes.decode("utf-8", errors="replace")
        truncated = False

        if len(stdout_text.encode("utf-8")) > cfg.max_output_bytes:
            stdout_text = stdout_text[:cfg.max_output_bytes] + "\n[OUTPUT TRUNCATED]"
            truncated = True

        if len(stderr_text.encode("utf-8")) > cfg.max_output_bytes:
            stderr_text = stderr_text[:cfg.max_output_bytes] + "\n[OUTPUT TRUNCATED]"
            truncated = True

        return SandboxResult(
            stdout=stdout_text,
            stderr=stderr_text,
            exit_code=exit_code,
            duration_seconds=duration,
            timed_out=timed_out,
            truncated=truncated,
        )
